class TestDotEnvPrecedence:
    """Verify .env file loading and precedence over defaults but under env vars."""

    def test_env_file_loaded(self, tmp_path, monkeypatch):
        """Settings should load values from a .env file in the working directory."""
        env_content = """
APP_NAME=env-file-app
PORT=9000
DEBUG_MODE=true
        """
        env_file = tmp_path / ".env"
        env_file.write_text(env_content)
        monkeypatch.chdir(tmp_path)

        settings = Settings()
        assert settings.APP_NAME == "env-file-app"
        assert settings.PORT == 9000
        assert settings.DEBUG_MODE is True

    def test_env_var_overrides_env_file(self, tmp_path, monkeypatch):
        """Environment variables should take precedence over .env file values."""
        env_content = "APP_NAME=env-file-app\nPORT=9000\n"
        env_file = tmp_path / ".env"
        env_file.write_text(env_content)
        monkeypatch.chdir(tmp_path)

        monkeypatch.setenv("APP_NAME", "env-var-app")
        monkeypatch.setenv("PORT", "8080")

        settings = Settings()
        assert settings.APP_NAME == "env-var-app"
        assert settings.PORT == 8080

    def test_env_file_missing_uses_defaults(self, tmp_path, monkeypatch):
        """Without .env file, defaults should be used."""
        monkeypatch.chdir(tmp_path)
        settings = Settings()
        assert settings.APP_NAME == "async-telemetry-gateway"
        assert settings.PORT == 8000


